import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plan 0026 — the toy course, cycle 3 (minting · substrate · honesty)","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/plans/0026-toy-course-cycle-3.md","filePath":"vendored/graphopt/project/plans/0026-toy-course-cycle-3.md"}`),a={name:`graphopt/project/plans/0026-toy-course-cycle-3.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-0026-—-the-toy-course-cycle-3-minting-·-substrate-·-honesty" tabindex="-1">Plan 0026 — the toy course, cycle 3 (minting · substrate · honesty) <a class="header-anchor" href="#plan-0026-—-the-toy-course-cycle-3-minting-·-substrate-·-honesty" aria-label="Permalink to “Plan 0026 — the toy course, cycle 3 (minting · substrate · honesty)”">​</a></h1><p>Depends on: ADR 0007 (semantic-atom minting), ADR 0008 (combinator presentation), ADR 0006 (ONNX backend), ADR 0003 (four dimensions); the toy&#39;s existing 12-level ladder (<code>docs/tutorials/course/README.md</code>).</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h2><p><code>docs/tutorials/course/</code> is the didactic surface — one idea per level, a worked example, an interactive, a checkpoint you must pass before advancing. It is <strong>stale by one cycle</strong>: the ladder ends at &quot;laws about laws&quot; and its prose still cites <em>two</em> machine-discovered laws and the 30-of-53 basis catalogue. This cycle changed the story in a way the course does not yet teach:</p><ul><li>the loop now <strong>mints and ships</strong> content (a law from a corpus op-tuple, a handler for a previously hand-written executor);</li><li><strong>truth ≠ pay</strong> — the same machinery honestly refused its apparent siblings, its first composed atom, and its own compression layer;</li><li><strong>exposure</strong> decides where discovery can pay at all (bimodal);</li><li>the IR is being re-presented as <strong>morphisms</strong> (Δ sharing, <code>loop</code> traces);</li><li>a <strong>second backend</strong> (ONNX) landed with zero core edits.</li></ul><p>Goal: pure understanding, so the reader can improve the real project after finishing the course.</p><h2 id="design-—-six-new-levels-12-→-18" tabindex="-1">Design — six new levels (12 → 18) <a class="header-anchor" href="#design-—-six-new-levels-12-→-18" aria-label="Permalink to “Design — six new levels (12 → 18)”">​</a></h2><p>Each follows the house format: <code>objective</code> (one sentence), a worked example, an interactive component, a gated <code>checkpoint</code> with a <code>why</code>.</p><table tabindex="0"><thead><tr><th>#</th><th>id</th><th>idea</th><th>interactive</th></tr></thead><tbody><tr><td>12</td><td><code>mint</code></td><td>the vocabulary grows itself — need → handler → laws → admission (ADR 0007&#39;s four layers)</td><td>pick a measured need from a small bank; watch the funnel: signature ✓/✗ → handler proposed+verified → laws synthesized → verdict</td></tr><tr><td>13</td><td><code>truthpay</code></td><td><strong>true is not the same as paying</strong> — guard synthesis, the adversarial sweep, and the refusal</td><td>try to break a naive guard by choosing shapes (a live mini-sweep: find a bad accept, see the synthesized exact guard); then the shipped-vs-rejected pair (<code>mul_unsq_nat</code> admitted; its apparent sibling refused)</td></tr><tr><td>14</td><td><code>exposure</code></td><td>where discovery can pay — the screen is bimodal</td><td>classify ops visible/invisible to the law LHSs; see 81/321 vs 140/321 and the ~1.5% yield</td></tr><tr><td>15</td><td><code>substrate</code></td><td>sharing is a morphism, recurrence is a <code>loop</code></td><td>translate a tiny DAG to a combinator term (Δ becomes explicit) and back; spell a recurrence as <code>loop(step)</code>; see the round-trip identity</td></tr><tr><td>16</td><td><code>ports</code></td><td>a backend is a port — nothing in core changes</td><td>swap the sink (torch ↔ ONNX-shaped) on a fixed core; the core panel stays byte-identical</td></tr><tr><td>17</td><td><code>honest</code></td><td>the ledger of negatives — methodology as a result</td><td>a gallery of measured refusals (ADR 0001 closed negative, the pay-null, the bounded-lane BiRefNet negative, the antiunify reach-null), each with its number; pick which claim each one kills</td></tr></tbody></table><h3 id="engine-additions-docs-tutorials-course-packages-engine" tabindex="-1">Engine additions (docs/tutorials/course/packages/engine) <a class="header-anchor" href="#engine-additions-docs-tutorials-course-packages-engine" aria-label="Permalink to “Engine additions (docs/tutorials/course/packages/engine)”">​</a></h3><p>Small, testable, faithful-to-the-real-thing:</p><ul><li><code>minting.ts</code> — a tiny funnel: needs → handler templates → law rows → verdicts, with counts matching the real ratios (documented as illustrative, not live-computed, where they are not computable in TS).</li><li><code>guards.ts</code> — a real mini-sweep over a small shape domain: a naive guard predicate, an enumerator of shapes, a counterexample search, and the exact guard; verdicts computed live.</li><li><code>exposure.ts</code> — an op → law-LHS-visible classifier over a fixed op list with FLOPs weights; the bimodal histogram computed live.</li><li><code>combinators.ts</code> — the basis (<code>leaf</code>/<code>arr</code>/<code>seq</code>/<code>par</code>/<code>dup</code>/<code>loop</code>), <code>dagToComb</code>/<code>combToDag</code> on the toy term language, round-trip check.</li><li><code>ports.ts</code> — a minimal <code>Source</code>/<code>Sink</code> pair and a core-mutation counter that must stay zero across a sink swap.</li></ul><h3 id="updates-to-existing-material" tabindex="-1">Updates to existing material <a class="header-anchor" href="#updates-to-existing-material" aria-label="Permalink to “Updates to existing material”">​</a></h3><ul><li>README ladder table (12 → 18) and the &quot;what is real&quot; callouts: <strong>four</strong> machine-discovered laws (<code>select_mul</code>, <code>softmax_fold</code>, <code>silu_fold</code>, <code>mul_unsq_nat</code>); the basis catalogue&#39;s current numbers; the ~1.5% corpus yield; the fused-lowering parity note.</li><li>Any level prose citing the two-law count or the 53-rule catalogue.</li><li>Bump <code>STORAGE_KEY</code> (<code>catopt-course-v1</code> → <code>v2</code>) — the level list changes shape.</li></ul><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to “Constraints”">​</a></h2><ul><li><strong>One idea per level</strong> — if a level needs two paragraphs of setup, it is two levels.</li><li>Interactives compute <strong>live</strong> wherever the toy can (guards, exposure histogram, round-trip); illustrative numbers are labelled as such and sourced from the retro they came from.</li><li>The course must not overclaim: the real system&#39;s honest negatives are taught as <em>results</em>, not footnotes.</li><li><code>vp check</code> (oxfmt/oxlint/tsgo) and <code>vp run -r test</code> (vitest) must pass; new engine modules need tests (the existing suite covers gating, reach, compare, tensions, coherence — extend the pattern).</li></ul><h2 id="falsification" tabindex="-1">Falsification <a class="header-anchor" href="#falsification" aria-label="Permalink to “Falsification”">​</a></h2><ul><li>A new level whose checkpoint can be passed without reading the interactive is a lecture, not a level — rewrite it.</li><li>If a new engine module cannot compute its idea live in TS, the idea belongs in prose in an existing level, not a new one.</li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};